create or replace function public.process_check_in() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ begin new.points_awarded:=case when public.is_qualifying_return_visit(new.user_id,new.location_id,new.checked_in_at,new.id) then 10 else 0 end; update public.profiles set total_check_ins=coalesce(total_check_ins,0)+1,updated_at=now() where id=new.user_id; return new; end; $function$;

create or replace function public.kleenest_map_check_in(p_location_id uuid,p_lat double precision default null,p_lng double precision default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare uid uuid:=auth.uid(); cid uuid; result jsonb; loc record; distance_m double precision; radius_m double precision; eligible boolean; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'LOCATION_REQUIRED'; end if; select id,latitude,longitude,coalesce(geofence_radius_m,150)::double precision radius_m into loc from public.locations where id=p_location_id and is_active=true and verification_status='verified'; if not found then raise exception 'LOCATION_NOT_VERIFIED'; end if; if loc.latitude is null or loc.longitude is null then raise exception 'LOCATION_COORDINATES_UNAVAILABLE'; end if; radius_m:=greatest(25,least(coalesce(loc.radius_m,150),5000)); distance_m:=6371000.0*2*asin(sqrt(power(sin(radians(p_lat-loc.latitude)/2),2)+cos(radians(loc.latitude))*cos(radians(p_lat))*power(sin(radians(p_lng-loc.longitude)/2),2))); if distance_m>radius_m then raise exception 'OUTSIDE_GEOFENCE: distance=% radius=%',round(distance_m),round(radius_m); end if; eligible:=public.is_qualifying_return_visit(uid,p_location_id,now(),null); insert into public.check_ins(user_id,location_id,latitude,longitude,distance_meters,verification_method,points_awarded,metadata) values(uid,p_location_id,p_lat,p_lng,distance_m,'gps',case when eligible then 10 else 0 end,jsonb_build_object('source','home_geofence','radius_meters',radius_m,'progression_eligible',eligible)) returning id into cid; return jsonb_build_object('success',true,'check_in_id',cid,'points_awarded',case when eligible then 10 else 0 end,'progression_eligible',eligible,'distance_meters',distance_m,'geofence_radius_meters',radius_m); end; $function$;

create or replace function public.create_check_in(p_place_id uuid,p_qr_token text default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_user uuid:=auth.uid();v_location uuid;v_business uuid;v_check uuid;v_points integer:=10;v_existing uuid;v_qr uuid;v_eligible boolean;begin if v_user is null then raise exception 'Authentication required';end if; select p.location_id,l.business_id into v_location,v_business from public.places p join public.locations l on l.id=p.location_id where p.id=p_place_id and p.is_active=true and l.is_active=true and l.verification_status='verified'; if v_location is null then raise exception 'Place not found or not verified';end if; if p_qr_token is not null and length(trim(p_qr_token))>0 then select id into v_qr from public.qr_codes where code=trim(p_qr_token) and active=true and location_id=v_location limit 1; if v_qr is null then raise exception 'Invalid or inactive QR code';end if; end if; v_eligible:=public.is_qualifying_return_visit(v_user,v_location,now(),null); insert into public.check_ins(user_id,location_id,qr_code_id,checked_in_at,verification_method,points_awarded,metadata) values(v_user,v_location,v_qr,now(),case when v_qr is null then 'place' else 'qr' end,case when v_eligible then v_points else 0 end,jsonb_build_object('place_id',p_place_id,'server_authoritative',true,'progression_eligible',v_eligible)) on conflict do nothing returning id into v_check; if v_check is null then select id into v_check from public.check_ins where user_id=v_user and location_id=v_location and checked_in_at>now()-interval '1 minute' order by checked_in_at desc limit 1; return jsonb_build_object('ok',true,'already_checked_in',true,'check_in_id',v_check,'id',v_check,'location_id',v_location,'business_id',v_business,'qr_code_id',v_qr,'points_awarded',0,'progression_eligible',false,'place_id',p_place_id);end if; return jsonb_build_object('ok',true,'already_checked_in',false,'check_in_id',v_check,'id',v_check,'location_id',v_location,'business_id',v_business,'qr_code_id',v_qr,'points_awarded',case when v_eligible then v_points else 0 end,'progression_eligible',v_eligible,'place_id',p_place_id);end $function$;
